import { cn } from "@/lib/utils"
import Image from "next/image"
import React from "react"

const Card = ({
  borderColor,
  cardData,
  cardStyle,
  imageContainerStyle,
  rounded,
}) => {
  return (
    <>
      {cardData.map((item, index) => (
        <div
          key={index}
          className={cn(
            "border p-4",
            borderColor ? borderColor : "border-gray-400",
            cardStyle,
            rounded ? rounded : "rounded-xl"
          )}>
          {/* Image Section  */}
          <div className={cn(imageContainerStyle ? imageContainerStyle : "aspect-[4/3]")}>
            <Image
              src={item.image}
              width={1000}
              height={1000}
              alt="not found"
              className="w-full h-full object-cover"
            />
          </div>
          {/* Card Content  */}
          <div className="p-4">
            <p className="text-lg font-semibold line-clamp-2 text-ellipsis">{item.title}</p>
            <svg viewBox="0 0 6 6" aria-hidden="true" class="dotted size-1">
              <circle r="3" cx="3" cy="3"></circle>
            </svg>
          </div>
        </div>
      ))}

    </>
  )
}

export default Card
